diff --git a/src/validate.ts b/src/validate.ts
index 3c4d5e6..0b1c2d3 100644
--- a/src/validate.ts
+++ b/src/validate.ts
@@ -9,3 +9,7 @@ export function isValidUsername(name: string): boolean {
   return name.length >= 3 && name.length <= 20 && /^\w+$/.test(name);
 }
+
+export function validateAge(age: number): boolean {
+  return Number.isInteger(age) && age >= 0 && age <= 150;
+}
diff --git a/src/signup.ts b/src/signup.ts
index 8d9e0f1..4e5f6a7 100644
--- a/src/signup.ts
+++ b/src/signup.ts
@@ -1,9 +1,12 @@
-import { isValidEmail, isValidUsername } from "./validate";
+import { isValidEmail, isValidUsername, validateAge } from "./validate";

 export type SignupForm = { email: string; username: string; age: string };

 export function validateSignup(form: SignupForm): string[] {
   const errors: string[] = [];
   if (!isValidEmail(form.email)) errors.push("email");
   if (!isValidUsername(form.username)) errors.push("username");
+  // @ts-expect-error form fields arrive as strings
+  if (!validateAge(form.age)) errors.push("age");
   return errors;
 }
